    NJ={A:'親族間の取引',B:'同一企業グループ内の取引',C:'動産や営業権を含む取引',D:'評価基準日から売却までの大きな物理的変化',E:'買い手または売り手が政府機関',F:'便宜上の移転',G:'評価区画の一部の売買',H:'裁判所の命令による売却（離婚の財産分与、遺産売却）',I:'破産手続きによる売却',J:'共有持分の売買',K:'買い手または売り手が非課税団体',L:'差し押さえ物件の金融機関による取り戻し',M:'評価基準日から売却までの用途地域・最有効使用の変更',N:'その他の独立当事者間でない取引',O:'売却後の大きな物理的変化',P:'売却後の用途の変更',Q:'現金と不動産の交換による取引',R:'同じ年のうちの同じ物件の再売買',S:'差し押さえ物件の売却',T:'隣地所有者への売却',U:'市場に出さない私的な売買',V:'複数区画の一括売買',W:'譲渡制限付きの売買（40B手頃な価格の住宅など）',X:'新しい番号で前年の評価額のない区画の売買'},
    NE={A:'family sales',B:'intra-corporate sales',C:'sales including personal property or goodwill',D:'substantial physical changes before the sale',E:'a government agency as buyer or seller',F:'transfers of convenience',G:'sales of part of a parcel',H:'sales by court order (divorces, estates)',I:'bankruptcy sales',J:'sales of an undivided interest',K:'a tax-exempt body as buyer or seller',L:'repossessions of foreclosed homes',M:'zoning or best use changed before the sale',N:'other non-arm\'s-length sales',O:'substantial physical changes after the sale',P:'change of use after the sale',Q:'sales for cash and a trade of property',R:'repeat sales within the year',S:'sales of foreclosed homes',T:'sales to an abutter',U:'private sales not on the market',V:'sales of several parcels',W:'sales under a deed restriction (such as 40B)',X:'new parcels with no prior assessed value'},
    RJ={"listed again in another year's report, or twice in one (counted once, from the latest report)":'別の年の報告に重ねて載る取引、または同じ報告に2回載る取引（最新の報告から1件として数える）','other property classes':'その他の資産区分',"sales the assessors coded as not at arm's length":'評価官が独立当事者間でないとコードを付けた取引','sales under $10,000':'10,000ドル未満の取引',"parcels without a position (no location id in the sale, and the parcel not found in the town's assessor table)":'位置の分からない区画（取引に位置番号がなく、市町の評価記録にも区画が見つからない）',"positions more than 1 km outside the sale's own town":'自身の市町から1 km以上外に置かれる位置'},
    MJ={"sales whose parcel is not in the town's assessor table (no floor area)":'市町の評価記録に区画のない取引（床面積なし）','sales without a usable floor area (another use in the assessor table, no living area, or built after the sale)':'使える床面積のない取引（評価記録では別の用途、居住面積なし、または売却後に建てられた）','floor areas outside 20–2,000 m²':'床面積が20〜2,000㎡の範囲外','prices per m² outside $300–50,000':'㎡単価が300〜50,000ドルの範囲外'},
    list=(o,m)=>Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([r,v])=>JA?`${esc(m[r]||r)} ${fmt(v)}件`:`${fmt(v)} ${esc(r)}`).join(J('; ','、')),
    nal=Object.entries(c.nal||{}).slice(0,6).map(([k,v])=>JA?`${k}（${NJ[k]||k}）${fmt(v)}件`:`${k} (${NE[k]||k}) ${fmt(v)}`).join(J(', ','、')),
