  none={contains:'in a suburb with no station',overlap:'in a suburb more than 1.2 km from every station'}[c.assign]||'more than 1.2 km from a station',near=c.assign==='overlap',month=['January','February','March','April','May','June','July','August','September','October','November','December'][bm-1],
