function startAnalytics(){if(!GA_ID)return;$('analyticsNote').hidden=false;if(location.hostname!=='ekinomics.com')return;const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+GA_ID;document.head.appendChild(s);window.dataLayer=window.dataLayer||[];window.gtag=function(){dataLayer.push(arguments)};gtag('js',new Date());gtag('config',GA_ID)}
function track(name,params={}){if(window.gtag)gtag('event',name,{edition:D?D.edition||'tokyo':'',...params})}
// The place menu is a disclosure: the button shows and hides the region links; Escape or a click elsewhere closes it.
(()=>{const b=$('placeButton'),m=$('placeMenu');if(!b)return;const set=open=>{m.hidden=!open;b.setAttribute('aria-expanded',String(open))};b.onclick=e=>{e.stopPropagation();set(m.hidden)};document.addEventListener('click',e=>{if(!m.hidden&&!m.contains(e.target))set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden){set(false);b.focus()}})})();
